// Normalize an Error Trigger payload into ONE compact log row.
const j = $input.first().json || {};
const ex = j.execution || {};
const err = ex.error || {};
const wf = j.workflow || {};

const code = err.httpCode || err.code || err.name || err.errorCode || '';
const desc = err.description || err.message || (typeof err === 'string' ? err : '') || 'Unknown error';
const nodeName = (err.node && err.node.name) || ex.lastNodeExecuted || '';

return [{ json: {
  timestamp: new Date().toISOString(),
  workflow_name: wf.name || '',
  node_name: nodeName,
  error_code: String(code),
  error_description: String(desc).slice(0, 500),
  execution_id: String(ex.id || ''),
  source: 'error_trigger',
} }];

// Turn historical error executions into log rows, keeping only NEW + important
// ones. Dedup by execution_id, skip older than 3 months / no detail.
const RETAIN_MS = 90 * 24 * 60 * 60 * 1000;
const cutoff = Date.now() - RETAIN_MS;

const existing = new Set();
for (const it of $('Read Existing Logs').all()) {
  const j = it.json || {};
  if (j && Object.keys(j).length && j.execution_id) existing.add(String(j.execution_id));
}

const seen = new Set();
const out = [];
for (const it of $('Fetch Error Executions').all()) {
  const e = it.json || {};
  const id = String(e.id || '');
  if (!id || existing.has(id) || seen.has(id)) continue;

  const whenStr = e.stoppedAt || e.startedAt || '';
  const when = Date.parse(whenStr);
  if (!isNaN(when) && when < cutoff) continue;

  const wfName = (e.workflowData && e.workflowData.name) || e.workflowName || '';
  const rd = (e.data && e.data.resultData) || {};
  const err = rd.error || {};
  const code = err.httpCode || err.code || err.name || err.errorCode || '';
  const desc = err.description || err.message || '';
  if (!desc) continue;
  const nodeName = (err.node && err.node.name) || rd.lastNodeExecuted || '';

  seen.add(id);
  out.push({ json: {
    timestamp: whenStr || new Date().toISOString(),
    workflow_name: wfName,
    node_name: nodeName,
    error_code: String(code),
    error_description: String(desc).slice(0, 500),
    execution_id: id,
    source: 'backfill',
  } });
}
return out;

// Find Logs rows older than 3 months and emit contiguous delete ranges.
// First data row is 2 (header on row 1). Emit ranges DESCENDING so deleting
// one range does not shift indexes of ranges not yet deleted.
const RETAIN_MS = 90 * 24 * 60 * 60 * 1000;
const cutoff = Date.now() - RETAIN_MS;

const rows = $('Read Logs (Retention)').all();
const oldRowNums = [];
for (let i = 0; i < rows.length; i++) {
  const j = rows[i].json || {};
  if (!j || !Object.keys(j).length) continue;
  const ts = Date.parse(j.timestamp || '');
  const sheetRow = i + 2;
  if (!isNaN(ts) && ts < cutoff) oldRowNums.push(sheetRow);
}

oldRowNums.sort((a, b) => a - b);
const ranges = [];
let start = null, prev = null;
for (const r of oldRowNums) {
  if (start === null) { start = r; prev = r; }
  else if (r === prev + 1) { prev = r; }
  else { ranges.push({ startIndex: start, numberToDelete: prev - start + 1 }); start = r; prev = r; }
}
if (start !== null) ranges.push({ startIndex: start, numberToDelete: prev - start + 1 });

ranges.sort((a, b) => b.startIndex - a.startIndex);
return ranges.map(r => ({ json: r }));

// Find Logs rows older than the retention window and emit contiguous delete
